await expect(async () => {
  if (!confirmation.test(page.url())) {
    await challengeFrame()
      ?.getByRole('button', { name: /complete/i })
      .first()
      .click({ timeout: 5_000 })
      .catch(() => {});
  }
  expect(page.url()).toMatch(confirmation);
}).toPass({ timeout: 60_000, intervals: [2_000, 3_000, 5_000] });

