  orderId: UUID;
  /** The order's PaymentIntent secret — the same one the new-card form confirms. */
  clientSecret: string;
  total: number;
  onSuccess: () => void;
  /** Asks the page to re-fetch the saved cards, after one turns out to be gone. */
  onCardsStale: () => void;
}

